    /// Restored classic names retain their authored palettes. Midnight without
    /// a mode is the older palette; Midnight Blue always stores its mode.
    static func resolve(name: String?, modeRaw: String?) -> (WyrmThemeID, WyrmThemeMode) {
        let stored = (name ?? "").trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let savedMode = WyrmThemeMode(rawValue: (modeRaw ?? "").trimmingCharacters(in: .whitespacesAndNewlines).lowercased())
        let key = ["paper", "graphite", "blush", "sun", "slate", "lilac", "forest"].contains(stored) || (stored == "midnight" && savedMode == nil) ? "classic_" + stored : stored
        if let mode = savedMode {
            return (WyrmThemeID(rawValue: key) ?? .sand, mode)
        }
        switch key {
        case "paper": return (.sand, .light)
        case "graphite": return (.sand, .dark)
        case "blush": return (.linen, .light)
        case "sun": return (.tangerine, .light)
        case "slate": return (.cyan, .light)
        case "lilac": return (.grape, .light)
        case "forest": return (.colonial3, .light)
        case "midnight": return (.midnight, .dark)
        case "": return (.classic_paper, .light)
        default:
            if let known = WyrmThemeID(rawValue: key) { return (known, known.defaultMode) }
            return (.sand, WyrmThemeID.sand.defaultMode)
        }
    }
}
